#!/usr/bin/env node
/**
 * Generates the in-SAP report that puts the CANONICAL maintenance helper body into SAP.
 *
 *   node scripts/generate-maintenance-carrier.mjs --offline
 *   node scripts/generate-maintenance-carrier.mjs --offline --check
 *   node scripts/generate-maintenance-carrier.mjs --program ZORVANTA_MAINT_DEPLOY_R02
 *
 * Why this carrier exists: the CAPABILITIES body of Z_ORVANTA_MAINT_READ (ZORVANTA_MAINT) is
 * generated by scripts/maintenance-diagnostic-source.mjs, which scripts/bootstrap-sap-helper.ps1
 * does not know about - it only carries LOG_READ, the two MCP_DDIC/DYNPRO APIs, MCP_EXECUTE and
 * OPS_READ. So the repository family's generator cannot be pointed at this helper, and there is no
 * include exporter for it either. Two other paths are dead:
 *
 *   - scripts/deploy-helper-capabilities.mjs writes the function module's own `source/main`. On
 *     SAP_BASIS 7.31 that PUT is refused with HTTP 423; of the 19 recorded runs on 2026-09-18, 12
 *     reached the write and all 12 failed, with no success ever.
 *   - The write helper operation WRITE_FUNCTION_SOURCE would do it, but the deployed write helper
 *     is at protocol 1.2 while that operation needs >= 2.11.
 *
 * What is left is a report program that rewrites the function group include itself, exactly like
 * the DDIC and repository carriers. This one is body-only: ARCHIVE_STATUS is answered from the
 * parameters the live helper already declares (IV_ACTION and friends), so the parameter interface
 * must NOT be rebuilt - the report keeps every include line through the end of the interface block
 * and splices the canonical body after it.
 *
 * The body source and every digest come from scripts/helper-capabilities-evidence.mjs, which is
 * the single authority for what this helper must end up declaring. The generator asserts, before
 * it emits anything, that the body it embeds is the reviewed intent (`intendedBodyHash`), that the
 * body it would replace is the recorded predecessor (`deployedNowBodyHash`) and that every
 * expected operation row is present and actually dispatched.
 *
 * Read-only against SAP: the live read only derives the baseline and the pre-flight assertions.
 * This script never writes, activates or transports anything in SAP.
 */
import assert from "node:assert/strict"
import { createHash } from "node:crypto"
import { readFile, writeFile } from "node:fs/promises"
import { resolve } from "node:path"
import { Client } from "@modelcontextprotocol/sdk/client/index.js"
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js"
import {
  bodyLinesHash,
  capabilityBodyDigest,
  capabilityHashSlotGroups,
  functionModuleBodyHash,
  helperCapabilityTargets,
  renderedCapabilityRows
} from "./helper-capabilities-evidence.mjs"

const argv = process.argv.slice(2)
const value = (flag, fallback) => {
  const i = argv.indexOf(flag)
  return i < 0 ? fallback : argv[i + 1]
}
const check = argv.includes("--check")
const offline = argv.includes("--offline")
const endpoint = value("--endpoint", process.env.ABAP_MCP_ENDPOINT ?? "http://127.0.0.1:4848/mcp")

const target = helperCapabilityTargets.maint
const HELPER = target.helper
const FUNCTION_GROUP = target.functionGroup
const POOL = `SAPL${FUNCTION_GROUP}`
// A carrier program name is single use: the creation tool refuses an existing object, and re-running
// an applied carrier is a no-op anyway, so a new deployment takes --program. The default is the name
// src/helper-carriers.ts publishes as the remedy for this helper, and test/helper-carriers.test.ts
// reads it back out of this file, so a rename here cannot leave a remedy pointing at nothing.
const DEFAULT_PROGRAM = "ZORVANTA_MAINT_DEPLOY"
const PROGRAM = value("--program", DEFAULT_PROGRAM)
const MARKER = "ORVANTA-MAINT-BODY-CARRIER"
const outFile = value(
  "--out",
  "C:/My/Workplace/Coding/vscode-abap/.doc/deploy-maint-body-1.1-r01.abap"
)

const body = [...target.generatorBody]
const expectedOperations = [...target.expectedOperations]

// ------------------------------------------------------------------------------------------------
// Offline calibration: the body must be the reviewed intent, and it must carry what it claims.
// ------------------------------------------------------------------------------------------------
assert.ok(body.length > 0, "the generator body is empty")
for (const line of body) {
  assert.ok(!line.includes("\t"), "the generator body must not carry tabs")
  assert.ok(line.length <= 72, `generator body line exceeds 72 columns: ${line}`)
}
assert.equal(
  bodyLinesHash(body),
  target.intendedBodyHash,
  `${HELPER}: the generator body is not the reviewed intent`
)
const digest = capabilityBodyDigest(body)
const hashGroups = capabilityHashSlotGroups(body)
assert.equal(hashGroups.length, 4, "SOURCE|HASH must carry four 16-character groups")
const deployedHashGroup = hashGroups[0]
assert.match(deployedHashGroup, /^[0-9a-f]{16}$/, "unexpected SOURCE|HASH group")

const rows = renderedCapabilityRows(body)
for (const row of expectedOperations) {
  assert.ok(rows.includes(row), `the body does not render the row ${row}`)
  const opcode = row.split("|")[1]
  assert.ok(
    body.some((line) => new RegExp(`(WHEN|OR)\\s+'${opcode}'`).test(line)),
    `opcode ${opcode} is rendered but never dispatched`
  )
}
assert.ok(rows.includes(`HELPER|${HELPER}`), "the body does not identify its helper")
assert.ok(rows.includes(`PROTOCOL|MIN|${target.expectedProtocol.min}`), "protocol minimum missing")
assert.ok(rows.includes(`PROTOCOL|MAX|${target.expectedProtocol.max}`), "protocol maximum missing")
assert.ok(rows.includes(`SOURCE|PACKAGE|${target.packageName}`), "package row missing")
assert.ok(
  rows.includes(`SOURCE|TRANSPORT|${target.transportRequest}|${target.transportTask}`),
  "the body does not record the request and task that carry it"
)
for (const line of body) {
  assert.ok(!/^\s*(FUNCTION|ENDFUNCTION)\b/i.test(line), "the body must not carry body fences")
  assert.ok(!line.includes(MARKER), "the body must not contain the carrier marker")
}
const ARCHIVE_ROW = expectedOperations.find((row) => row.startsWith("OPERATION|ARCHIVE_STATUS|"))
assert.ok(ARCHIVE_ROW, "ARCHIVE_STATUS is not among the expected operations")

// ------------------------------------------------------------------------------------------------
// Live pre-flight: the report must replace the body SAP actually holds, not an assumed one.
// ------------------------------------------------------------------------------------------------
let live = null
if (!offline) {
  const client = new Client({ name: "maintenance-carrier-generator", version: "1.0.0" })
  await client.connect(new StreamableHTTPClientTransport(new URL(endpoint)))
  const read = await client.callTool(
    {
      name: "read_function_module_interface",
      arguments: { connectionId: "w200", functionName: HELPER }
    },
    undefined,
    { timeout: 300000 }
  )
  assert.equal(read.isError ?? false, false, "reading the live helper failed")
  const payload = JSON.parse((read.content ?? []).map((c) => c.text ?? "").join(""))
  live = payload.source ?? []
  await client.close()

  assert.equal(live[0].trim(), `FUNCTION ${HELPER}.`, `unexpected live first line: ${live[0]}`)
  assert.match(String(live.at(-1)).trim(), /^ENDFUNCTION\./i, "unexpected live last line")
  // The live read is the same text the report reads back with READ REPORT, so its line count is the
  // baseline the report pins. `read_function_module_interface` returns the SAP-side include view.
  const liveBodyHash = functionModuleBodyHash(live.join("\n"))
  const isPredecessor = liveBodyHash === target.deployedNowBodyHash
  const isAlreadyDeployed = liveBodyHash === target.intendedBodyHash
  assert.ok(
    isPredecessor || isAlreadyDeployed,
    `${HELPER}: the deployed body is neither the recorded predecessor nor the reviewed intent\n` +
      `  live     ${liveBodyHash}\n  recorded ${target.deployedNowBodyHash}`
  )
  if (isAlreadyDeployed) {
    console.warn(
      `note: ${HELPER} already carries the reviewed body; this carrier would only be idempotent.`
    )
  }
  // Everything the body names must already exist in the deployed parameter interface: the carrier
  // does not rebuild it, so a name that is missing would fail at GENERATE time inside SAP.
  const liveNames = new Set(
    [...live.join("\n").matchAll(/\b((?:IV|EV|ES|ET|CT|IT|IS|CV|CS)_[A-Z0-9_]+)\b/g)].map(
      (match) => match[1]
    )
  )
  const referenced = new Set(
    [...body.join("\n").matchAll(/\b((?:IV|EV|ES|ET|CT|IT|IS|CV|CS)_[A-Z0-9_]+)\b/g)].map(
      (match) => match[1]
    )
  )
  const undeclared = [...referenced].filter((name) => !liveNames.has(name))
  assert.deepEqual(
    undeclared,
    [],
    `${HELPER}: the body names parameters the deployed interface does not declare`
  )
  console.log(
    `live baseline: ${live.length} lines, body hash ${liveBodyHash.slice(0, 16)} (${
      isAlreadyDeployed ? "already the reviewed body" : "the recorded predecessor"
    })`
  )
}

// ------------------------------------------------------------------------------------------------
// Emit the report.
// ------------------------------------------------------------------------------------------------
/**
 * ABAP ends a statement with a period that is NOT inside a string literal. `WRITE: / 'not found.'`
 * terminates nothing: the compiler keeps reading and reports the failure at the NEXT statement, so
 * the message points somewhere else entirely.
 *
 * That is how the first version of this carrier failed activation - `WRITE: / 'ERROR: the deployed
 * include does not declare OPERATION|ARCHIVE_STATUS|1.1|R.'` left the statement open and SAP
 * answered `[E] line 1: the statement before RETURN is not terminated (period missing)` for a
 * program whose first line is a perfectly good REPORT statement. Every line looked correct by eye,
 * so the emitted output is checked here and this shape cannot leave the generator again.
 */
function assertStatementsTerminated(lines) {
  const codeOnly = (line) => {
    let out = ""
    let inLiteral = false
    for (let i = 0; i < line.length; i += 1) {
      const c = line[i]
      if (inLiteral) {
        if (c === "'") {
          if (line[i + 1] === "'") {
            i += 1
            continue
          }
          inLiteral = false
        }
        continue
      }
      if (c === "'") {
        inLiteral = true
        continue
      }
      if (c === '"') break
      out += c
    }
    return out
  }
  // The shapes this generator deliberately continues onto the next line: a comma-separated
  // CONSTANTS/DATA chain, a split ELSEIF condition, and a split GENERATE REPORT.
  const continues = [/^AND\b/i, /^OR\b/i, /^ELSEIF\b/i, /^LINE\b/i, /^GENERATE\b/i]
  const unterminated = []
  lines.forEach((line, index) => {
    const trimmed = line.trim()
    if (trimmed === "" || trimmed.startsWith("*")) return
    const code = codeOnly(line).trim()
    if (code === "" || code.endsWith(".") || code.endsWith(",")) return
    if (continues.some((pattern) => pattern.test(code))) return
    unterminated.push(`${index + 1}: ${line}`)
  })
  assert.deepEqual(
    unterminated,
    [],
    "an emitted statement does not end with a period, which SAP reports at the next statement"
  )
}

const payloadDigest = createHash("sha256")
  .update([`FUNCTION ${HELPER}.`, ...body, "ENDFUNCTION."].join("\n"), "utf8")
  .digest("hex")
  .slice(0, 16)
const literal = (s) => `'${String(s).replace(/'/g, "''")}'`

const report = []
report.push(`REPORT ${PROGRAM.toLowerCase()}.`)
report.push("")
report.push("* GENERATED by scripts/generate-maintenance-carrier.mjs -- do not edit by hand.")
report.push(`* ${MARKER}`)
report.push(`* Target   : ${HELPER} (${FUNCTION_GROUP})`)
report.push(`* Transport: ${target.transportRequest} (recorded; never released by this report)`)
report.push(
  live
    ? `* Baseline : the deployed include measured ${live.length} lines in the ADT view. The count is`
    : "* Baseline : NOT READ (generated with --offline); the report carries no line count."
)
if (live) {
  report.push(
    "*            reported, not enforced: that view trims trailing blank lines and READ REPORT does"
  )
  report.push("*            not, so a fatal comparison stops a carrier on a formatting difference.")
}
report.push(
  `* Deploys  : the CANONICAL generator body - protocol ${target.expectedProtocol.min}..${target.expectedProtocol.max}, ` +
    `${expectedOperations.length} operations, ${body.length} body lines.`
)
report.push(
  "*            Body-only carrier: ARCHIVE_STATUS is answered from the parameters the deployed"
)
report.push(
  "*            helper already declares, so the parameter interface is kept exactly as deployed"
)
report.push("*            and only the implementation body is replaced.")
report.push(`* Fingerprint: the deployed body publishes SOURCE|HASH ${digest}, which is what`)
report.push(
  "*            get_capability_report must echo back; the first group is the idempotency key."
)
report.push("")
report.push(`CONSTANTS: c_group  TYPE c LENGTH 30 VALUE ${literal(FUNCTION_GROUP)},`)
report.push(`           c_func   TYPE c LENGTH 30 VALUE ${literal(HELPER)},`)
report.push(`           c_marker TYPE c LENGTH 40 VALUE ${literal(MARKER)},`)
report.push(`           c_request TYPE e071-trkorr VALUE ${literal(target.transportRequest)},`)
report.push(`           c_hash   TYPE c LENGTH 16 VALUE ${literal(deployedHashGroup)},`)
report.push(
  `           c_digest TYPE c LENGTH 16 VALUE '${digest.slice(0, 16)}'${live ? "," : "."}`
)
if (live) report.push(`           c_lines  TYPE i VALUE ${live.length}.`)
report.push("")
report.push("DATA: lt_new TYPE TABLE OF abaptxt255,")
report.push("      lt_body TYPE TABLE OF abaptxt255,")
report.push("      lt_cur TYPE TABLE OF abaptxt255,")
report.push("      ls_new TYPE abaptxt255,")
report.push("      ls_cur TYPE abaptxt255,")
report.push("      lv_name TYPE c LENGTH 30,")
report.push("      lv_head TYPE c LENGTH 20,")
report.push("      lv_found TYPE c LENGTH 1,")
report.push("      lv_count TYPE i,")
report.push("      lv_keep TYPE i,")
report.push("      lv_ops TYPE i,")
report.push("      lv_in_interface TYPE c LENGTH 1,")
report.push("      lv_arch_ok TYPE c LENGTH 1,")
report.push("      lv_hash_ok TYPE c LENGTH 1,")
report.push("      lv_iface_ok TYPE c LENGTH 1,")
report.push("      lv_line TYPE string,")
report.push("      lv_suffix TYPE tfdir-include,")
report.push("      lv_msg TYPE string,")
report.push("      lv_msg_line TYPE i,")
report.push("      lv_msg_word TYPE string.")
report.push("")
report.push("START-OF-SELECTION.")
report.push("  WRITE: / c_marker.")
report.push("  WRITE: / 'Target      :', c_group.")
report.push("  WRITE: / 'Helper      :', c_func.")
report.push("  WRITE: / 'Transport   :', c_request.")
report.push(`  WRITE: / 'Body        :', ${body.length}, 'lines; digest', c_digest.`)
if (live) report.push("  WRITE: / 'Baseline    :', c_lines, 'deployed lines pinned.'.")
report.push("  SKIP 1.")
report.push("")
report.push("  REFRESH lt_body.")
for (const line of body) {
  report.push(`  CLEAR ls_new. ls_new-line = ${literal(line)}. APPEND ls_new TO lt_body.`)
}
report.push("")
report.push("  DESCRIBE TABLE lt_body LINES lv_count.")
report.push(`  IF lv_count <> ${body.length}.`)
report.push("    WRITE: / 'ERROR: body line count mismatch:', lv_count.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("")
report.push("* Locate the function group include the function module actually lives in.")
report.push("  SELECT SINGLE include FROM tfdir INTO lv_suffix WHERE funcname = c_func.")
report.push("  IF sy-subrc <> 0 OR lv_suffix IS INITIAL.")
report.push("    WRITE: / 'ERROR: no TFDIR include suffix for', c_func.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  CONCATENATE 'L' c_group 'U' lv_suffix INTO lv_name.")
report.push("  REFRESH lt_cur.")
report.push("  READ REPORT lv_name INTO lt_cur.")
report.push("  IF sy-subrc <> 0 OR lt_cur IS INITIAL.")
report.push("    WRITE: / 'ERROR: cannot read function group include', lv_name.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  DESCRIBE TABLE lt_cur LINES lv_count.")
report.push("")
report.push(
  "* Idempotency: the deployed body publishes SOURCE|HASH, and this carrier's group only exists"
)
report.push("* in the include once the body below has been applied.")
report.push("  CLEAR lv_found.")
report.push("  LOOP AT lt_cur INTO ls_cur.")
report.push("    IF ls_cur-line CS c_marker OR ls_cur-line CS c_hash.")
report.push("      lv_found = 'X'. EXIT.")
report.push("    ENDIF.")
report.push("  ENDLOOP.")
report.push("  IF lv_found = 'X'.")
report.push("    WRITE: / 'NOTHING TO DO: this carrier is already applied.'.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("")
if (live) {
  report.push(
    `* Baseline: this include measured ${live.length} lines in the ADT view the carrier was generated`
  )
  report.push(
    "* from. That view trims trailing blank lines and READ REPORT does not, so the count is"
  )
  report.push(
    "* reported and NOT enforced: a fatal comparison here stops the carrier on a formatting"
  )
  report.push(
    "* difference, which from outside is indistinguishable from a carrier that did nothing"
  )
  report.push(
    "* (return code 0, unchanged body). What guards the baseline instead: the deployed body"
  )
  report.push(
    "* hash checked before this carrier was generated, the idempotency check above, and the"
  )
  report.push(
    "* interface check below - the interface half is taken from the live include, never rebuilt."
  )
  report.push("  IF lv_count <> c_lines.")
  report.push(
    "    WRITE: / 'NOTE: include line count differs from the generated baseline:', lv_count, c_lines."
  )
  report.push("  ENDIF.")
  report.push("")
}
report.push("  READ TABLE lt_cur INTO ls_cur INDEX 1.")
report.push("  lv_head = ls_cur-line.")
report.push("  TRANSLATE lv_head TO UPPER CASE.")
report.push("  IF lv_head(8) <> 'FUNCTION'.")
report.push("    WRITE: / 'ERROR: existing include does not start with FUNCTION'.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("")
report.push("* Locate the end of the parameter interface: keep it, replace only the body after it.")
report.push(
  "* A source-based interface opens with IMPORTING/EXPORTING/CHANGING/TABLES and closes with"
)
report.push("* the first period; a classic interface closes with its own separator line.")
report.push("  CLEAR: lv_keep, lv_in_interface.")
report.push("  LOOP AT lt_cur INTO ls_cur.")
report.push("    lv_line = ls_cur-line.")
report.push("    CONDENSE lv_line.")
report.push("    IF lv_in_interface = 'X'.")
report.push("      IF lv_line CP '*.'.")
report.push("        lv_keep = sy-tabix. EXIT.")
report.push("      ENDIF.")
report.push("    ELSEIF lv_line CS '\"-----------------------------------------'")
report.push("       AND sy-tabix <> 2.")
report.push("      lv_keep = sy-tabix. EXIT.")
report.push("    ELSEIF lv_line CP 'IMPORTING*' OR lv_line CP 'EXPORTING*'")
report.push("       OR lv_line CP 'CHANGING*' OR lv_line CP 'TABLES*'.")
report.push("      lv_in_interface = 'X'.")
report.push("    ENDIF.")
report.push("  ENDLOOP.")
report.push("  IF lv_keep IS INITIAL.")
report.push("    WRITE: / 'ERROR: cannot locate the parameter interface. Refusing to replace the'.")
report.push("    WRITE: / 'include, because that would drop the function module parameters.'.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  WRITE: / 'Interface   : kept through line', lv_keep, 'of', lv_count.")
report.push("")
report.push(
  "* The interface half comes from the live include, so prove it is the reviewed interface before"
)
report.push(
  "* installing the body that depends on it. This is a content check, not a line count: it is what"
)
report.push("* replaces the line-count baseline guard as the fatal precondition.")
report.push("  CLEAR lv_ops.")
report.push("  LOOP AT lt_cur INTO ls_cur.")
report.push("    IF sy-tabix > lv_keep. EXIT. ENDIF.")
report.push("    IF ls_cur-line CS 'VALUE(IV_ACTION)'. lv_ops = lv_ops + 1. ENDIF.")
report.push("    IF ls_cur-line CS 'VALUE(EV_RESULT)'. lv_ops = lv_ops + 1. ENDIF.")
report.push("  ENDLOOP.")
report.push("  IF lv_ops < 2.")
report.push(
  "    WRITE: / 'ERROR: the deployed interface does not declare the reviewed parameters:', lv_ops."
)
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("")
report.push("  REFRESH lt_new.")
report.push("  LOOP AT lt_cur INTO ls_cur.")
report.push("    IF sy-tabix > lv_keep. EXIT. ENDIF.")
report.push("    APPEND ls_cur TO lt_new.")
report.push("  ENDLOOP.")
report.push("  CLEAR ls_new. APPEND ls_new TO lt_new.")
report.push("  APPEND LINES OF lt_body TO lt_new.")
report.push("  CLEAR ls_new. ls_new-line = 'ENDFUNCTION.'. APPEND ls_new TO lt_new.")
report.push("")
report.push("  INSERT REPORT lv_name FROM lt_new.")
report.push("  IF sy-subrc <> 0.")
report.push("    WRITE: / 'ERROR: INSERT REPORT failed', sy-subrc.")
report.push("    ROLLBACK WORK.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("")
report.push(`  GENERATE REPORT '${POOL}' MESSAGE lv_msg`)
report.push("    LINE lv_msg_line WORD lv_msg_word.")
report.push("  IF sy-subrc <> 0.")
report.push("    WRITE: / 'ERROR: GENERATE failed:', lv_msg.")
report.push("    WRITE: / '  body line:', lv_msg_line, 'word:', lv_msg_word.")
report.push("    WRITE: / '  the active version is unchanged; nothing was activated.'.")
report.push("    ROLLBACK WORK.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  UPDATE enlfdir SET generated = 'X' WHERE funcname = c_func.")
report.push("  IF sy-subrc <> 0.")
report.push("    WRITE: / 'ERROR: generated flag update failed', sy-subrc.")
report.push("    ROLLBACK WORK.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  COMMIT WORK AND WAIT.")
report.push("")
report.push(
  `* Post-condition: the include must carry ${expectedOperations.length} operation rows, the new`
)
report.push(
  "* ARCHIVE_STATUS row, this carrier's SOURCE|HASH group and the deployed parameter interface."
)
report.push("  REFRESH lt_cur.")
report.push("  READ REPORT lv_name INTO lt_cur.")
report.push("  IF sy-subrc <> 0.")
report.push("    WRITE: / 'ERROR: cannot re-read the include after the write'.")
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  CLEAR: lv_ops, lv_arch_ok, lv_hash_ok, lv_iface_ok.")
report.push("  LOOP AT lt_cur INTO ls_cur.")
report.push("    IF ls_cur-line CS 'OPERATION|'.")
report.push("      lv_ops = lv_ops + 1.")
report.push("    ENDIF.")
report.push(`    IF ls_cur-line CS ${literal(ARCHIVE_ROW)}.`)
report.push("      lv_arch_ok = 'X'.")
report.push("    ENDIF.")
report.push("    IF ls_cur-line CS 'SOURCE|HASH|' AND ls_cur-line CS c_hash.")
report.push("      lv_hash_ok = 'X'.")
report.push("    ENDIF.")
report.push("    IF ls_cur-line CS 'VALUE(IV_ACTION)'.")
report.push("      lv_iface_ok = 'X'.")
report.push("    ENDIF.")
report.push("  ENDLOOP.")
report.push("  WRITE: / 'Operations  :', lv_ops, 'rows in the deployed include.'.")
report.push("  IF lv_arch_ok <> 'X'.")
report.push(`    WRITE: / 'ERROR: the deployed include does not declare ${ARCHIVE_ROW}'.`)
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  IF lv_hash_ok <> 'X'.")
report.push(
  "    WRITE: / 'ERROR: the deployed include does not publish this carrier SOURCE|HASH.'."
)
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  IF lv_iface_ok <> 'X'.")
report.push(
  "    WRITE: / 'ERROR: the deployed include no longer declares the parameter interface.'."
)
report.push("    RETURN.")
report.push("  ENDIF.")
report.push(`  IF lv_ops < ${expectedOperations.length}.`)
report.push(
  `    WRITE: / 'ERROR: expected at least ${expectedOperations.length} OPERATION rows, found', lv_ops.`
)
report.push("    RETURN.")
report.push("  ENDIF.")
report.push("  WRITE: / 'Interface   : parameter interface preserved in the deployed include.'.")
report.push("  WRITE: / 'DONE: helper regenerated;', lv_ops, 'capability rows written.'.")
report.push(
  "  WRITE: / 'Next: sap_helper_status ping, then get_capability_report and confirm the sourceHash'."
)
report.push(`  WRITE: / '      and PROTOCOL|MAX|${target.expectedProtocol.max} for ${HELPER}'.`)
report.push("")

assertStatementsTerminated(report)
const text = report.join("\n")
const widest = report.reduce((max, line) => Math.max(max, line.length), 0)
const payloadWidest = body.reduce((max, line) => Math.max(max, line.length), 0)
console.log(`report widest line: ${widest} columns (payload body is capped at ${payloadWidest})`)

if (check) {
  let existing = null
  try {
    existing = await readFile(resolve(outFile), "utf8")
  } catch {
    existing = null
  }
  assert.ok(existing !== null, `${outFile} does not exist; run without --check first`)
  if (existing !== text) {
    console.error(`out of date: ${outFile} differs from the freshly generated carrier`)
    process.exitCode = 1
  } else {
    console.log(`up to date: ${outFile}`)
  }
} else {
  await writeFile(resolve(outFile), text, "utf8")
  console.log(`wrote ${outFile}`)
  console.log(`  program    ${PROGRAM}`)
  console.log(`  helper     ${HELPER} (${FUNCTION_GROUP}, pool ${POOL})`)
  console.log(
    `  body       ${body.length} lines, hash ${bodyLinesHash(body).slice(0, 16)}, digest ${digest.slice(0, 16)}`
  )
  console.log(
    `  operations ${expectedOperations.length}: ${expectedOperations.map((row) => row.split("|")[1]).join(", ")}`
  )
  console.log(`  marker     ${MARKER} / SOURCE|HASH group ${deployedHashGroup}`)
  console.log(`  transport  ${target.transportRequest} (recorded, never released)`)
  if (live) console.log(`  baseline   ${live.length} deployed lines pinned as c_lines`)
}
